ALTER COLLECTION docs SET SECURITY POLICY {
  'department_actions': [
    'read',
    'search'
  ],
  'owner_actions': [
    'read',
    'search',
    'update',
    'delete'
  ],
  'templates': {
    'finance': {
      'department': 'Finance',
      'classification': 'internal',
      'properties': {
        '/text': {
          'classification': 'internal',
          'actions': [
            'read',
            'query',
            'write'
          ]
        }
      },
      'representations': {
        'dense': {
          'source_fields': [
            '/text'
          ],
          'classification': 'internal'
        }
      }
    },
    'hr': {
      'department': 'HR',
      'classification': 'internal',
      'properties': {
        '/text': {
          'classification': 'internal',
          'actions': [
            'read',
            'query',
            'write'
          ]
        }
      },
      'representations': {
        'dense': {
          'source_fields': [
            '/text'
          ],
          'classification': 'internal'
        }
      }
    }
  }
};

PIPELINE
  VECTOR v { SEARCH chunks NEAR [1,0] LIMIT 20 }
  RELATIONAL r { SQL SELECT id, chunk_ref FROM documents LIMIT 20 }
  INNER JOIN r ON r.chunk_ref = v.record_ref
  RETURN r.id, v.score
  LIMIT 10;

TRANSACTION {
  SQL INSERT INTO documents (id, title) VALUES ('doc-1', 'Atomic document');
  VECTOR UPSERT INTO chunks {id: 'chunk-1', vector: [1,0]}, {id: 'source-1', vector: [0,1]};
  GRAPH CONNECT chunks 'chunk-1' -> CITES -> 'source-1';
};
